&reftitle.description;
public boolIo\Poll\Backend::supportsEdgeTriggering
Checks whether Io\Poll\Event::EdgeTriggered can be used with this backend. Only Io\Poll\Backend::Epoll and Io\Poll\Backend::Kqueue support it.

  &reftitle.examples;

   Requesting edge triggering only when it is supported


<?php
use Io\Poll\Context;
use Io\Poll\Event;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();

$events = [Event::Read];
if ($context->getBackend()->supportsEdgeTriggering()) {
    $events[] = Event::EdgeTriggered;
}

$watcher = $context->add(new StreamPollHandle($reader), $events);
var_dump($watcher->getWatchedEvents());


   &example.outputs.similar;


array(2) {
  [0]=>
  enum(Io\Poll\Event::Read)
  [1]=>
  enum(Io\Poll\Event::EdgeTriggered)
}
